const groups = new Map(DETAILS.trim().split("\n").map((line) => line.split("|")));
const points = leaves().flatMap((leaf) => {
  const details = groups.get(leaf.name);
  if (!details) throw new Error(`缺少考纲知识点：${leaf.id}`);
  const parentId = [leaf.subject, ...leaf.path, leaf.name].join("/");
  return details.split(",").map((detail) => {
    const [name, ...aliases] = detail.replace(/I\/O|TCP\/IP|CSMA\/(?:CD|CA)/g, (term) => term.replace("/", "／")).split("/").map((term) => term.replace("／", "/"));
    return { id: `${parentId}#${name}`, leaf: parentId, subject: leaf.subject, name, aliases };
  });
});
const byId = new Map(points.map((point) => [point.id, point]));
const byLeaf = new Map();
for (const point of points) {
  if (!byLeaf.has(point.leaf)) byLeaf.set(point.leaf, []);
  byLeaf.get(point.leaf).push(point);
}

function validPointIds(ids, subject) {
  return [...new Set(ids || [])].filter((id) => byId.get(id)?.subject === subject);
}

const norm = (text) => String(text || "").toLowerCase().replace(/\s/g, "").replace(/／/g, "/");
const namesBySubject = new Map();
for (const point of points) {
  if (!namesBySubject.has(point.subject)) namesBySubject.set(point.subject, new Map());
  const index = namesBySubject.get(point.subject);
  for (const term of new Set([point.name, ...point.aliases].map(norm))) {
    if (!index.has(term)) index.set(term, []);
    index.get(term).push(point);
  }
}

function exactPoints(subject, tags) {
  const index = namesBySubject.get(subject);
  if (!index) return [];
  return [...new Set((tags || []).flatMap((tag) => index.get(norm(tag)) || []))];
}

const STATUSES = ["已讲待测", "答错待复测", "部分做对", "提示后做对", "独立做对"];
function createCoverage(store) {
  /** extra：从快练、模考、题库作答和错题重做推出来的状态事件（{pointId,status,at,question}），与会话里记下的合并按时间取最新。 */
  function list(leafIds, extra = []) {
    const latest = new Map();
    const tests = new Map();
    const events = [...store.list("coverage"), ...extra].filter((e) => e && e.pointId && e.at).sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0));
    for (const event of events) {
      const previous = latest.get(event.pointId);
      if (event.status !== "已讲待测") tests.set(event.pointId, (tests.get(event.pointId) || 0) + 1);
      if (event.status !== "已讲待测" || !previous) latest.set(event.pointId, event);
    }
    return leafIds.flatMap((id) => (byLeaf.get(id) || []).map((point) => {
      const last = latest.get(point.id);
      return { id: point.id, name: point.name, leaf: id, status: last?.status || "未测", at: last?.at, question: last?.question, tests: tests.get(point.id) || 0 };
    }));
  }

  function record({ subject, pointIds, status, question, chatId, bankId }) {
    const ids = validPointIds(pointIds, subject);
    if (!ids.length || !STATUSES.includes(status)) return 0;
    const events = store.list("coverage");
    const at = new Date().toISOString();
    const rows = ids.map((pointId) => ({ pointId, status, question: String(question || "").slice(0, 300), chatId, bankId, at }));
    const key = (e) => JSON.stringify([e.pointId, e.question, e.chatId, e.bankId]);
    const latest = new Map(events.filter((e) => e.chatId === chatId).map((e) => [key(e), e.status]));
    const additions = rows.filter((e) => latest.get(key(e)) !== e.status);
    if (additions.length) store.saveList("coverage", [...events, ...additions]);
    return ids.length;
  }
  return { list, record };
}

module.exports = { points, byId, byLeaf, exactPoints, validPointIds, createCoverage };
